"""
Tests for Phase 1.7 (Instance Subset Builder).
Verifies reproducibility, correct stratum counts, sampling rules,
and loading of instances from configs/instances.yaml.
"""

from pathlib import Path

import yaml

from linebench.instances.subset import (
    build_instance_subsets,
    freeze_instances_yaml,
    load_subset_instance,
)


def test_build_instance_subsets_counts():
    """Verify exact stratum counts generated by protocol selection rules."""
    res = build_instance_subsets(
        seed=42,
        simulation_seed=2026,
        scholl_large_sample_size=15,
        generated_instances_per_cell=3,
    )
    meta = res["metadata"]

    # 191 Scholl instances (n <= 100) + 15 sampled from large = 206
    assert meta["classical_instances_count"] == 206

    # Generated: 21 cells * 3 instances * 3 sizes (20, 50, 100) = 189
    assert meta["generated_instances_count"] == 189

    # Total benchmark instances = 206 + 189 = 395
    assert meta["total_benchmark_instances"] == 395

    # Simulation subset = exactly 30
    assert meta["simulation_instances_count"] == 30


def test_instance_subsets_reproducibility():
    """Verify that identical seeds produce bit-identical instance selections."""
    run1 = build_instance_subsets(seed=42, simulation_seed=2026)
    run2 = build_instance_subsets(seed=42, simulation_seed=2026)

    assert run1["metadata"] == run2["metadata"]
    ids1 = [x["id"] for x in run1["benchmark_instances"]]
    ids2 = [x["id"] for x in run2["benchmark_instances"]]
    assert ids1 == ids2

    sim_ids1 = [x["id"] for x in run1["simulation_instances"]]
    sim_ids2 = [x["id"] for x in run2["simulation_instances"]]
    assert sim_ids1 == sim_ids2


def test_load_subset_instances_sample():
    """Verify that entries can be successfully loaded as Instance objects."""
    yaml_path = Path("configs/instances.yaml")
    if not yaml_path.exists():
        freeze_instances_yaml()

    with open(yaml_path, "r", encoding="utf-8") as f:
        data = yaml.safe_load(f)

    benchmark_instances = data["benchmark_instances"]

    # Find a classical entry and a generated entry
    classical_entry = next(i for i in benchmark_instances if i["stratum"] == "classical")
    generated_entry = next(i for i in benchmark_instances if i["stratum"] == "generated")

    c_inst = load_subset_instance(classical_entry)
    assert c_inst.num_tasks == classical_entry["num_tasks"]
    assert c_inst.cycle_time == classical_entry["cycle_time"]

    g_inst = load_subset_instance(generated_entry)
    assert g_inst.num_tasks == generated_entry["num_tasks"]
    assert g_inst.cycle_time == generated_entry["cycle_time"]


def test_lower_bounds_never_exceed_published_optima():
    """Phase 1 Exit Criterion: Lower bound LB must never exceed published optimum."""
    yaml_path = Path("configs/instances.yaml")
    with open(yaml_path, "r", encoding="utf-8") as f:
        data = yaml.safe_load(f)

    # Test sample across simulation subset
    sim_subset = data["simulation_instances"]
    from linebench.instances.bounds import compute_lower_bound

    for entry in sim_subset:
        opt = entry["optimal_stations"]
        if opt is not None:
            inst = load_subset_instance(entry)
            lb = compute_lower_bound(inst)
            assert lb <= opt, (
                f"Violation on {entry['id']}: lower bound {lb} > published optimum {opt}"
            )
